// Rebuild generated TypeScript constants. Never downloads or rewrites upstream.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';

const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const root = new URL('./', import.meta.url);
const provenance = JSON.parse(readFileSync(new URL('provenance.json', root), 'utf8'));
const files = {};
for (const name of [...Object.keys(provenance.files), 'provenance.json']) {
  const bytes = readFileSync(new URL(name, root));
  if (provenance.files[name] && hash(bytes) !== provenance.files[name].sha256) throw Error('Pinned upstream source differs.');
  files[name] = { sha256: hash(bytes), gzip: gzipSync(bytes, { level: 9 }).toString('base64') };
}
const adapter = readFileSync(new URL('adapter.mjs', root), 'utf8');
const template = readFileSync(new URL('harness-template.mjs', root), 'utf8');
writeFileSync(new URL('../../src/domain/deburr-bundle.ts', root),
  '// Generated by vendor/second-case/build-bundle.mjs. Complete unchanged upstream source is MIT licensed.\n'
  + '// See vendor/second-case/provenance.json and embedded LICENSE files.\n'
  + 'export const DEBURR_FILES = ' + JSON.stringify(files) + ' as const;\n'
  + 'export const DEBURR_ADAPTER = ' + JSON.stringify(adapter) + ';\n'
  + 'export const DEBURR_ADAPTER_SHA256 = ' + JSON.stringify(hash(adapter)) + ';\n'
  + 'export const DEBURR_HARNESS_TEMPLATE = ' + JSON.stringify(template) + ';\n');
const config = JSON.parse(readFileSync(new URL('oracle.json', root), 'utf8'));
for (const revision of ['affected', 'fixed']) {
  for (const file of config[revision].files) {
    file.sha256 = hash(readFileSync(new URL('../../' + file.path, root)));
  }
}
writeFileSync(new URL('oracle.json', root), JSON.stringify(config, null, 2) + '\n');
